   260	  /**
   261	   * see <a href="https://docs.mongodb.com/manual/reference/operator/query/not/">mongo query manual $not</a>
   262	   * NOT operator is mongo is a little specific and can't be applied on all levels
   263	   * $not: { $or ... } will not work and should be transformed to $nor
   264	   */
   265	  private Bson negate(Expression expression) {
   266	    if (!(expression instanceof Call)) {
   267	      return Filters.not(expression.accept(this));
   268	    }
   269	
   270	    Call notCall = (Call) expression;
   271	    Operator notOperator = notCall.operator();
   272	
   273	    if (notOperator == Operators.NOT) {
   274	      // NOT NOT a == a
   275	      return notCall.arguments().get(0).accept(this);
   276	    } else if (notOperator == Operators.EQUAL) {
   277	      return this.newCall(notCall, Operators.NOT_EQUAL);
   278	    } else if (notOperator == Operators.NOT_EQUAL) {
   279	      return this.newCall(notCall, Operators.EQUAL);
   280	    } else if (notOperator == Operators.IN) {
   281	      return this.newCall(notCall, Operators.NOT_IN);
   282	    } else if (notOperator == Operators.NOT_IN) {
   283	      return this.newCall(notCall, Operators.IN);
   284	    } else if (notOperator == Operators.OR) {
   285	      return Filters.nor(notCall.arguments().stream().map(a -> a.accept(this)).collect(Collectors.toList()));
   286	    } else if (notOperator == Operators.AND) {
   287	      // NOT A and B == (NOT A) or (NOT B)
   288	      return Filters.or(notCall.arguments().stream().map(this::negate).collect(Collectors.toList()));
   289	    } else if (notOperator == OptionalOperators.IS_ABSENT || notOperator == OptionalOperators.IS_PRESENT) {
   290	      Operator newOp = notOperator == OptionalOperators.IS_ABSENT ? OptionalOperators.IS_PRESENT : OptionalOperators.IS_ABSENT;
   291	      return this.newCall(notCall, newOp);
   292	    } else if (notOperator == IterableOperators.IS_EMPTY || notOperator == IterableOperators.NOT_EMPTY) {
   293	      Operator newOp = notOperator == IterableOperators.IS_EMPTY ? IterableOperators.NOT_EMPTY : IterableOperators.IS_EMPTY;
   294	      return this.newCall(notCall, newOp);
   295	    }
   296	
   297	    // don't really know how to negate here
   298	    return Filters.not(notCall.accept(this));
   299	  }
