   305	  private static Operator negateOperator(Operator operator) {
   306	    if (operator == Operators.EQUAL) {
   307	      return Operators.NOT_EQUAL;
   308	    } else if (operator == Operators.NOT_EQUAL) {
   309	      return Operators.EQUAL;
   310	    } else if (operator == Operators.IN) {
   311	      return Operators.NOT_IN;
   312	    } else if (operator == Operators.NOT_IN) {
   313	      return Operators.IN;
   314	    } else if (operator == OptionalOperators.IS_ABSENT) {
   315	      return OptionalOperators.IS_PRESENT;
   316	    } else if (operator == OptionalOperators.IS_PRESENT) {
   317	      return OptionalOperators.IS_ABSENT;
   318	    } else if (operator == IterableOperators.IS_EMPTY) {
   319	      return IterableOperators.NOT_EMPTY;
   320	    } else if (operator == IterableOperators.NOT_EMPTY) {
   321	      return IterableOperators.IS_EMPTY;
   322	    } else {
   323	      throw new UnsupportedOperationException("No negation for " + operator + " defined");
   324	    }
   325	  }
