   327	  /** Simple holder for the result of unwinding consecutive ANY operators. */
   328	  private static class UnwoundAny {
   329	    final Path path;
   330	    final Call inner;
   331	    UnwoundAny(Path path, Call inner) {
   332	      this.path = path;
   333	      this.inner = inner;
   334	    }
   335	  }
