   337	  /**
   338	   * Unwinds consecutive ANY operators, accumulating the path segments.
   339	   * E.g. ANY(collar.tags, inner) => UnwoundAny(collar.tags, inner)
   340	   */
   341	  private static UnwoundAny unwindAny(Call call) {
   342	    Path path = null;
   343	    while (call.operator() == IterableOperators.ANY) {
   344	      Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for ANY got %s", call.arguments().size());
   345	      Preconditions.checkArgument(call.arguments().get(0) instanceof Path, "%s is not a path", call.arguments().get(0));
   346	      Preconditions.checkArgument(call.arguments().get(1) instanceof Call, "%s is not a call", call.arguments().get(1));
   347	      Path subPath = (Path) call.arguments().get(0);
   348	      path = appendPath(path, subPath);
   349	      call = (Call) call.arguments().get(1);
   350	    }
   351	    return new UnwoundAny(path, call);
   352	  }
