   354	  /**
   355	   * Appends all members of suffix onto prefix, returning the combined path.
   356	   * Returns prefix if suffix is null, suffix if prefix is null.
   357	   */
   358	  private static Path appendPath(Path prefix, Path suffix) {
   359	    if (suffix == null) return prefix;
   360	    if (prefix == null) return suffix;
   361	    for (java.lang.reflect.Member member : suffix.members()) {
   362	      prefix = prefix.append(member);
   363	    }
   364	    return prefix;
   365	  }
