   367	  /**
   368	   * Recursively builds a MongoDB filter condition for use inside $elemMatch.
   369	   * Handles arbitrarily nested AND/OR/NOT operators by traversing the expression tree.
   370	   *
   371	   * @param expr the expression to convert (must be a Call)
   372	   * @return a Bson filter suitable for use inside Filters.elemMatch()
   373	   */
   374	  private Bson buildElemMatchCondition(Expression expr) {
   375	    return this.buildElemMatchCondition(expr, null);
   376	  }
   377	
   378	  private Bson buildElemMatchCondition(Expression expr, Path anyPrefix) {
   379	    if (!(expr instanceof Call)) {
   380	      throw new IllegalArgumentException("Expected Call but got " + expr);
   381	    }
   382	
   383	    Call call = (Call) expr;
   384	    Operator op = call.operator();
   385	
   386	    // Handle AND/OR recursively
   387	    if (op == Operators.AND || op == Operators.OR) {
   388	      List<Bson> conditions = new ArrayList<>();
   389	
   390	      for (Expression arg : call.arguments()) {
   391	        Preconditions.checkArgument(arg instanceof Call, "Expected Call but got %s", arg);
   392	        Call argCall = (Call) arg;
   393	
   394	        if (argCall.operator() == Operators.AND || argCall.operator() == Operators.OR) {
   395	          conditions.add(this.buildElemMatchCondition(arg, anyPrefix));
   396	        } else if (argCall.operator() == IterableOperators.ANY) {
   397	          // Nested ANY inside AND/OR: unwind and dispatch
   398	          UnwoundAny unwound = unwindAny(argCall);
   399	          Path nestedPrefix = appendPath(anyPrefix, unwound.path);
   400	          Call inner = unwound.inner;
   401	          if (inner.operator() == Operators.AND || inner.operator() == Operators.OR || inner.operator() == Operators.NOT) {
   402	            conditions.add(this.buildElemMatchCondition(inner, nestedPrefix));
   403	          } else {
   404	            conditions.add(this.buildLeafCondition(inner, nestedPrefix));
   405	          }
   406	        } else {
   407	          conditions.add(this.buildLeafCondition(argCall, anyPrefix));
   408	        }
   409	      }
   410	
   411	      return op == Operators.AND ? Filters.and(conditions) : Filters.or(conditions);
   412	    }
   413	
   414	    // For top-level NOT or leaf conditions
   415	    return this.buildLeafCondition(call, anyPrefix);
   416	  }
   417	
   418	  private Bson buildLeafCondition(Call call, Path anyPrefix) {
   419	    Operator operator = call.operator();
   420	
   421	    // Handle NOT operator by unwrapping and negating the inner operator
   422	    if (operator == Operators.NOT) {
   423	      Preconditions.checkArgument(call.arguments().get(0) instanceof Call, "%s is not a call", call.arguments().get(0));
   424	      call = (Call) call.arguments().get(0);
   425	
   426	      // Unwrap any nested ANY operators, accumulating path into anyPrefix
   427	      if (call.operator() == IterableOperators.ANY) {
   428	        UnwoundAny unwound = unwindAny(call);
   429	        anyPrefix = appendPath(anyPrefix, unwound.path);
   430	        call = unwound.inner;
   431	      }
   432	
   433	      // If after unwrapping we find AND/OR, apply De Morgan's laws
   434	      if (call.operator() == Operators.AND || call.operator() == Operators.OR) {
   435	        return this.applyDeMorgansLaw(call, anyPrefix);
   436	      }
   437	
   438	      operator = negateOperator(call.operator());
   439	    } else {
   440	      operator = call.operator();
   441	    }
   442	
   443	    // Extract and reconstruct the path
   444	    Preconditions.checkArgument(call.arguments().get(0) instanceof Path, "%s is not a path", call.arguments().get(0));
   445	    Path fullPath = reconstructFullPath(Visitors.toPath(call.arguments().get(0)));
   446	    fullPath = appendPath(anyPrefix, fullPath);
   447	
   448	    if (fullPath == null) {
   449	      // Scalar array element inside $elemMatch — no field name needed
   450	      return this.buildScalarElemMatchCondition(call, operator);
   451	    }
   452	
   453	    // Build the final condition
   454	    return this.buildCondition(call, operator, fullPath);
   455	  }
   456	
   457	  private Bson applyDeMorgansLaw(Call call, Path anyPrefix) {
   458	    Operator op = call.operator();
   459	    List<Bson> negatedConditions = new ArrayList<>();
   460	
   461	    for (Expression arg : call.arguments()) {
   462	      Call negatedArg = Expressions.unaryCall(Operators.NOT, arg);
   463	      negatedConditions.add(this.buildLeafCondition(negatedArg, anyPrefix));
   464	    }
   465	
   466	    // Apply De Morgan's law: flip AND <-> OR
   467	    return op == Operators.AND ? Filters.or(negatedConditions) : Filters.and(negatedConditions);
   468	  }
