    79	  private static class LocalVisitor implements ExpressionVisitor<Object> {
    80	
    81	    private static final PathExtractor EXTRACTOR = new ReflectionExtractor();
    82	    private final Object instance;
    83	
    84	    private LocalVisitor(Object instance) {
    85	      this.instance = instance;
    86	    }
    87	
    88	    @Override
    89	    public Object visit(Call call) {
    90	      final Operator op = call.operator();
    91	      final List<Expression> args = call.arguments();
    92	
    93	
    94	      if (op == Operators.NOT) {
    95	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
    96	        final Object value = args.get(0).accept(this);
    97	
    98	        if (value == UNKNOWN) {
    99	          return UNKNOWN;
   100	        }
   101	
   102	        if (value instanceof Boolean) {
   103	          return !(Boolean) value;
   104	        }
   105	
   106	        throw new UnsupportedOperationException(String.format("Expected boolean for op %s but got %s", op, value.getClass().getName()));
   107	      }
   108	
   109	      if (op == IterableOperators.IS_EMPTY || op == IterableOperators.NOT_EMPTY) {
   110	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
   111	        final Object value = args.get(0).accept(this);
   112	        if (value == UNKNOWN) {
   113	          return UNKNOWN;
   114	        }
   115	
   116	        Preconditions.checkArgument(value instanceof Iterable, "%s not iterable", value.getClass().getName());
   117	        final boolean empty = Iterables.isEmpty((Iterable<?>) value);
   118	        return (op == IterableOperators.IS_EMPTY) == empty;
   119	      }
   120	
   121	      if (op == OptionalOperators.IS_ABSENT || op == OptionalOperators.IS_PRESENT) {
   122	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
   123	        final Object left = args.get(0).accept(this);
   124	
   125	        if (left == UNKNOWN) {
   126	         return (op == OptionalOperators.IS_ABSENT);
   127	        }
   128	
   129	        return (op == OptionalOperators.IS_ABSENT) ? Objects.isNull(left) : Objects.nonNull(left);
   130	      }
   131	
   132	      if (op == StringOperators.TO_UPPER_CASE || op == StringOperators.TO_LOWER_CASE) {
   133	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 but was %s", args.size());
   134	        Object value = args.get(0).accept(this);
   135	        if (value == null || value == UNKNOWN) {
   136	          return UNKNOWN;
   137	        }
   138	
   139	        Preconditions.checkArgument(value instanceof CharSequence, "Expected %s got %s", CharSequence.class.getSimpleName(), value.getClass().getName());
   140	        return op == StringOperators.TO_UPPER_CASE ? value.toString().toUpperCase() : value.toString().toLowerCase();
   141	      }
   142	
   143	      if (op == Operators.AND || op == Operators.OR) {
   144	        Preconditions.checkArgument(!args.isEmpty(), "empty args for %s", op);
   145	        final boolean shortCircuit = op == Operators.OR;
   146	        boolean prev = !shortCircuit;
   147	        for (Expression exp:args) {
   148	          final Object result = exp.accept(this);
   149	          if (result == null || result == UNKNOWN) {
   150	            return UNKNOWN;
   151	          } else if (prev == shortCircuit || Objects.equals(shortCircuit, result)) {
   152	            return shortCircuit;
   153	          } else {
   154	            // continue evaluating
   155	            prev = (Boolean) result;
   156	          }
   157	        }
   158	
   159	        return prev;
   160	      }
   161	      
   162	      if (op == IterableOperators.ANY) {
   163	        Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s got %s", call, call.arguments().size());
   164	        
   165	        final Object left = call.arguments().get(0).accept(this);
   166	        Preconditions.checkArgument(left instanceof Iterable, "%s is not iterable", left);
   167	        @SuppressWarnings("unchecked")
   168	        final Iterable<Object> leftIterable = (Iterable<Object>) left;
   169	        Preconditions.checkArgument(call.arguments().get(1) instanceof Call, "%s is not a call", call.arguments().get(1));
   170	        final Call rightCall = (Call) call.arguments().get(1);
   171	
   172	        final Stream<Object> stream = StreamSupport.stream(leftIterable.spliterator(), false);
   173	        return stream.anyMatch(r -> ExpressionInterpreter.of(rightCall).asPredicate().test(r));
   174	      }
   175	
   176	      if (op.arity() == Operator.Arity.BINARY) {
   177	        Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s got %s", call, call.arguments().size());
   178	        final Object left = call.arguments().get(0).accept(this);
   179	        if (left == UNKNOWN) {
   180	          return UNKNOWN;
   181	        }
   182	
   183	        final Object right = call.arguments().get(1).accept(this);
   184	        if (right == UNKNOWN) {
   185	          return UNKNOWN;
   186	        }
   187	
   188	        return binaryCall(call, left, right);
   189	      }
   190	
   191	      throw new UnsupportedOperationException("Don't know how to handle " + op);
   192	    }
