   215	        final int size = ((Number) right).intValue();
   216	        return Iterables.size(iter) == size;
   217	      }
   218	
   219	      if (op == IterableOperators.CONTAINS) {
   220	        Preconditions.checkArgument(left instanceof Iterable, "%s is not iterable", left);
