  }


  private IterableChecker<List<String>, String> ids(IntegerHolderCriteria criteria) {
    return CriteriaChecker.<TypeHolder.IntegerHolder>ofReader(repository.find(criteria)).toList(TypeHolder.IntegerHolder::id);
